<script>
    // Simulation Logic
    const transcriptLines =;
    let lineIndex = 0;
    let transcriptInterval;

    // Start transcript simulation on load
    window.onload = function() {
        transcriptInterval = setInterval(() => {
            if (lineIndex < transcriptLines.length) {
                document.getElementById('transcriptText').innerText = transcriptLines[lineIndex];
                document.getElementById('transcriptText').style.opacity = 1;
                lineIndex++;
            } else {
                lineIndex = 0; // Loop for visual effect
            }
        }, 2000);
    };

    function stopRecording() {
        clearInterval(transcriptInterval);
        const ambientUI = document.getElementById('ambientInterface');
        const reviewUI = document.getElementById('reviewInterface');

        // Visual transition
        ambientUI.style.opacity = '0';
        setTimeout(() => {
            ambientUI.style.display = 'none';
            reviewUI.style.display = 'flex';
        }, 500);
    }

    function handleKey(e) {
        if (e.key === 'Enter') sendMessage();
    }

    function sendMessage() {
        const input = document.getElementById('userInput');
        const history = document.getElementById('chatHistory');
        const text = input.value.trim();

        if (!text) return;

        // User Message
        const userDiv = document.createElement('div');
        userDiv.className = 'msg msg-user';
        userDiv.innerText = text;
        history.appendChild(userDiv);

        input.value = '';
        history.scrollTop = history.scrollHeight;

        // Simulate AI Latency
        setTimeout(() => {
            const aiDiv = document.createElement('div');
            aiDiv.className = 'msg msg-ai';

            // Simple rule-based responses
            if (text.toLowerCase().includes("follow up") |

| text.toLowerCase().includes("week")) {
                aiDiv.innerHTML = "I have added a <strong>follow-up appointment</strong> in 2 weeks to the Plan section.";
            } else if (text.toLowerCase().includes("referral")) {
                aiDiv.innerHTML = "I've drafted a referral letter to <strong>Orthopedics</strong> based on the exam findings.";
            } else {
                aiDiv.innerHTML = "Updated. I've adjusted the note to reflect that change.";
            }

            history.appendChild(aiDiv);
            history.scrollTop = history.scrollHeight;
        }, 1000);
    }
</script>

