<script>
    const chatStream = document.getElementById('chatStream');
    const input = document.getElementById('userInput');
    const typing = document.getElementById('typingIndicator');

    function handleEnter(e) {
        if (e.key === 'Enter') sendMessage();
    }

    function sendMessage() {
        const text = input.value.trim();
        if (!text) return;

        // User Message
        addMessage(text, 'msg-user');
        input.value = '';

        // Simulate AI Thinking
        showTyping(true);

        setTimeout(() => {
            showTyping(false);
            generateResponse(text);
        }, 1200);
    }

    function addMessage(text, className) {
        const div = document.createElement('div');
        div.className = message ${className};
        div.innerText = text;
        chatStream.insertBefore(div, typing); // Insert before typing indicator
        chatStream.scrollTop = chatStream.scrollHeight;
    }

    function showTyping(show) {
        typing.style.display = show? 'flex' : 'none';
        chatStream.scrollTop = chatStream.scrollHeight;
    }

    function generateResponse(userText) {
        const lower = userText.toLowerCase();
        let response = "";

        // Triage Safety Check
        if (lower.includes('chest pain') |

| lower.includes('breathing') |
| lower.includes('emergency')) {
            response = "⚠️ This sounds like a medical emergency. Please hang up and dial 911 immediately. I cannot schedule appointments for emergencies.";
        }
        // Scheduling Logic
        else if (lower.includes('yes') |

| lower.includes('sure') |
| lower.includes('schedule')) {
            response = "Great! I have the following openings: \n1. Tuesday at 10:00 AM\n2. Thursday at 2:00 PM\n\nWhich works for you? (Type 1 or 2)";
        }
        else if (lower.includes('1') |

| lower.includes('tuesday')) {
            response = "I've held that spot for you. To confirm, please reply with your Date of Birth (MM/DD/YYYY).";
        }
        else if (lower.match(/\d{2}\/\d{2}\/\d{4}/)) { // Simple Date Regex
            response = "Thanks! Your appointment for Tuesday at 10:00 AM is CONFIRMED. ✅\n\nPlease bring your insurance card. See you then!";
        }
        else {
            response = "I can help you book an appointment. Are you looking to come in next week? Reply YES to see times.";
        }

        addMessage(response, 'msg-ai');
    }
</script>

