                    content = "<strong>Summary:</strong> 60yo F with HTN, HLD, and likely new onset DM2. Labs show worsening glycemic control. Needs eye exam and foot check.";
                }

                aiMsg.innerHTML = <div class="card-body">${content}</div>;
                feed.appendChild(aiMsg);
                feed.scrollTop = feed.scrollHeight;
            }, 800);
        }
    }

    // Start simulation
    loadInsights();
</script>

