<script>
    const transcript =;

    let index = 0;

    function startSimulation() {
        const stream = document.getElementById('liveText');
        const dxList = document.getElementById('dxList');
        const rxList = document.getElementById('rxList');

        // Reset
        stream.innerHTML = "";
        dxList.innerHTML = "";
        rxList.innerHTML = "";
        index = 0;

        const interval = setInterval(() => {
            if (index >= transcript.length) {
                clearInterval(interval);
                return;
            }

            const item = transcript[index];

            // Typewriter effect for transcript
            stream.innerHTML = "${item.text}";
            stream.style.color = "white";
            setTimeout(() => { stream.style.color = "#9aa0a6"; }, 1400);

            // Create Action Card if needed
            if (item.type) {
                createCard(item.type, item.title, item.sub);
            }

            index++;
        }, 2000);
    }

    function createCard(type, title, sub) {
        const card = document.createElement('div');
        let typeClass = "";
        let container = null;

        if (type === 'dx') { typeClass = 'card-dx'; container = document.getElementById('dxList'); }
        else if (type === 'rx') { typeClass = 'card-rx'; container = document.getElementById('rxList'); }
        else if (type === 'lab') { typeClass = 'card-lab'; container = document.getElementById('rxList'); }

        card.className = action-card ${typeClass};
        card.innerHTML =
            <div class="card-content">
                <div class="card-title">${title}</div>
                <div class="card-sub">${sub}</div>
            </div>
            <div class="card-actions">
                <i class="fas fa-pen"></i>
                <i class="fas fa-trash"></i>
            </div>
        ;

        container.insertBefore(card, container.firstChild);
    }

    function handleCommand(e) {
        if (e.key === 'Enter') {
            const cmd = e.target.value;
            // Simulate Magic Editing
            const rxCards = document.getElementById('rxList').children;
            if (rxCards.length > 0) {
                rxCards.querySelector('.card-sub').innerText = UPDATED: ${cmd};
                rxCards.style.background = "#4e5256"; // Visual feedback
            }
            e.target.value = "";
        }
    }
</script>

